// continue's composer waits on a boot beacon to api.continue.dev that can
// hang on a sandboxed runner (the env-proxy seeds were inert there) and
// never mounts. PR #111 already resolves that host instantly — RESOLVE,
// never reject, so no unhandled rejection. The [boot-trace] lines record
// every OTHER outbound request cn makes during boot (global fetch, node
// http/https, DNS) with ms since this preload loaded, plus one line when
// the TUI first reads the keyboard; stderr is teed into pane.log, so the
// CI artifact names the second, runner-only boot gate.
const t0 = Date.now();
const trace = (kind, method, host, path) => {
  try {
    const line = `[boot-trace] +${Date.now() - t0}ms ${kind} ${method ? method + " " : ""}${host || "?"}${path || ""}`;
    console.error(line.length > 300 ? line.slice(0, 300) + "…" : line);
  } catch {}
};

const realFetch = globalThis.fetch;
globalThis.fetch = (input, init) => {
  const url = typeof input === "string" ? input : input && (input.url ?? String(input));
  if (typeof url === "string" && url.includes("api.continue.dev")) {
    console.error("[beacon-kill] api.continue.dev resolved instantly");
    return Promise.resolve(new Response("[]"));
  }
  try {
    const u = new URL(url, "http://x.invalid");
    trace("fetch", init?.method || (input && input.method), u.host, u.pathname + u.search);
  } catch { console.error("[boot-trace] fetch <unparsed url>"); }
  return realFetch(input, init);
};

// node http/https: cn may open ClientRequests directly instead of fetch.
// http.get/https.get route through this.request on the module exports, so
// one wrapper per module covers both.
for (const mod of [require("http"), require("https")]) {
  const real = mod.request;
  mod.request = (arg, opts, cb) => {
    try {
      let method, host, path;
      if (typeof arg === "string" || (arg && typeof arg.href === "string")) {
        const u = new URL(arg);
        host = u.host; path = u.pathname + u.search;
      } else if (arg && typeof arg === "object") {
        method = arg.method;
        host = arg.hostname ? arg.hostname + (arg.port ? ":" + arg.port : "") : arg.host;
        path = arg.path;
      }
      if (opts && typeof opts === "object") {
        method = method || opts.method;
        host = host || (opts.hostname ? opts.hostname + (opts.port ? ":" + opts.port : "") : opts.host);
        path = path || opts.path;
      }
      trace("request", method, host, path);
    } catch { console.error("[boot-trace] request <unparsed args>"); }
    return real.call(mod, arg, opts, cb);
  };
}

// DNS is the floor under every socket API (bundled undici and node tls both
// land here), so a hostname that hangs the boot shows up even if cn
// bypasses fetch and http.request entirely.
const dns = require("dns");
const realLookup = dns.lookup;
dns.lookup = (...args) => {
  trace("dns", null, args[0], null);
  return realLookup.apply(dns, args);
};
const realPLookup = dns.promises.lookup;
dns.promises.lookup = (...args) => {
  trace("dns", null, args[0], null);
  return realPLookup.apply(dns.promises, args);
};

// one line at the first keyboard read — the composer mount point
let sawStdin = false;
process.stdin.on("readable", () => {
  if (!sawStdin) { sawStdin = true; console.error("[boot-trace] composer reads stdin"); }
});
